package ru.fifth.horror.client;
import net.minecraft.client.MinecraftClient;import net.minecraft.client.font.TextRenderer;import net.minecraft.client.render.*;import net.minecraft.client.render.block.entity.BlockEntityRenderer;import net.minecraft.client.render.block.entity.BlockEntityRendererFactory;import net.minecraft.client.util.math.MatrixStack;import net.minecraft.util.math.RotationAxis;import org.joml.Matrix4f;import ru.fifth.horror.block.TelevisionBlockEntity;
public final class TelevisionRenderer implements BlockEntityRenderer<TelevisionBlockEntity>{private final TextRenderer text;public TelevisionRenderer(BlockEntityRendererFactory.Context c){text=c.getTextRenderer();}@Override public void render(TelevisionBlockEntity be,float delta,MatrixStack ms,VertexConsumerProvider vp,int light,int overlay){if(be.getRecording().isBlank()&&be.getStaticTicks()<=0)return;ms.push();ms.translate(.5,.64,-.002);ms.multiply(RotationAxis.POSITIVE_X.rotationDegrees(0));ms.scale(.0125f,-.0125f,.0125f);String s=be.getStaticTicks()>0?"▓▒░ FIVEN VHS ░▒▓":"REC  "+be.getRecording();float x=-text.getWidth(s)/2f;text.draw(s,x,0,be.getStaticTicks()>0?0xFFB0B0B0:0xFF8C2020,false,ms.peek().getPositionMatrix(),vp,TextRenderer.TextLayerType.POLYGON_OFFSET,0,light);ms.pop();}}
